using GestionTubos.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace GestionTubos.Infrastructure.Configurations;
public sealed class IngresoClienteConfiguration:IEntityTypeConfiguration<IngresoCliente>{public void Configure(EntityTypeBuilder<IngresoCliente>b){b.ToTable("IngresosClientes");b.HasKey(x=>x.Id);b.HasIndex(x=>x.Numero).IsUnique();b.Property(x=>x.Numero).HasMaxLength(30);b.Property(x=>x.ClienteNombre).HasMaxLength(250);b.Property(x=>x.DocumentoCliente).HasMaxLength(50);b.Property(x=>x.PersonaEntrega).HasMaxLength(150);b.Property(x=>x.DocumentoEntrega).HasMaxLength(20);b.Property(x=>x.Usuario).HasMaxLength(256);b.Property(x=>x.UsuarioId).HasMaxLength(450);b.Property(x=>x.Observaciones).HasMaxLength(1000);b.HasOne(x=>x.Cliente).WithMany().HasForeignKey(x=>x.ClienteId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class IngresoClienteDetalleConfiguration:IEntityTypeConfiguration<IngresoClienteDetalle>{public void Configure(EntityTypeBuilder<IngresoClienteDetalle>b){b.ToTable("IngresosClientesDetalle");b.HasKey(x=>x.Id);b.HasIndex(x=>x.TuboId).IsUnique().HasFilter("[FechaRetiroUtc] IS NULL");b.HasIndex(x=>new{x.IngresoClienteId,x.TuboId}).IsUnique();b.Property(x=>x.Codigo).HasMaxLength(50);b.Property(x=>x.Gas).HasMaxLength(200);b.Property(x=>x.Capacidad).HasMaxLength(100);b.HasOne(x=>x.IngresoCliente).WithMany(x=>x.Detalles).HasForeignKey(x=>x.IngresoClienteId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Tubo).WithMany().HasForeignKey(x=>x.TuboId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.RemitoEntrega).WithMany().HasForeignKey(x=>x.RemitoEntregaId).OnDelete(DeleteBehavior.Restrict);}}
